 public static void Install(DanceMatch match){if(match.GetComponent<DanceVenue>()!=null)return;var venue=match.gameObject.AddComponent<DanceVenue>();venue.match=match;var root=new GameObject("Diesel Discotheque · touring venue").transform;
  var dark=SportsEventAuthoring.Mat(Folder,"DJ touring enamel",new Color(.025f,.03f,.055f),.4f);var pink=SportsEventAuthoring.Mat(Folder,"Laser pink",new Color(1,.05f,.4f),.5f);var cyan=SportsEventAuthoring.Mat(Folder,"Electric cyan",new Color(.03f,.8f,1),.5f);
  SportsEventAuthoring.Box("Front-lit DJ mixing booth",new Vector3(0,1.8f,10),new Vector3(9,2.3f,2.7f),dark,null,root);SportsEventAuthoring.Box("Illuminated DJ booth inset",new Vector3(0,1.8f,8.60f),new Vector3(8.4f,1.4f,.05f),cyan,null,root);
  for(int side=-1;side<=1;side+=2){var plate=GameObject.CreatePrimitive(PrimitiveType.Cylinder);plate.name="DJ turntable platter";plate.transform.SetParent(root,false);plate.transform.localPosition=new Vector3(side*2,3,10);plate.transform.localScale=new Vector3(1.8f,.05f,1.8f);plate.GetComponent<Renderer>().sharedMaterial=pink;UnityEngine.Object.DestroyImmediate(plate.GetComponent<Collider>());}
  var dj=UnityEngine.Object.Instantiate(match.dancers[0].truck.visuals.gameObject,root).transform;dj.name="Resident DJ truck · actual owned model";dj.localPosition=new Vector3(0,3,11);dj.localRotation=Quaternion.Euler(0,180,0);dj.localScale*=.8f;StripPhysics(dj.gameObject);venue.dj=dj;
  var deckRims=UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsInactive.Exclude).Where(r=>r.name=="Luminous stage perimeter").OrderBy(r=>r.transform.position.x).ToArray();for(int i=0;i<match.dancers.Length;i++)if(i<deckRims.Length)match.dancers[i].deck=deckRims[i].transform;
