  Directory.CreateDirectory("Assets/TruckDanceOff/Animation");var controllerPath="Assets/TruckDanceOff/Animation/Concert audience.controller";var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(controllerPath);if(controller==null){controller=AnimatorController.CreateAnimatorControllerAtPath(controllerPath);var dance=AssetDatabase.LoadAllAssetsAtPath("Assets/UTS_FullPack/Models/People/Animations/man/Dance_man.FBX").OfType<AnimationClip>().First(c=>!c.name.StartsWith("__preview"));var cheer=AssetDatabase.LoadAllAssetsAtPath("Assets/UTS_FullPack/Models/People/Animations/man/Cheer.FBX").OfType<AnimationClip>().FirstOrDefault(c=>!c.name.StartsWith("__preview"));var state=controller.AddMotion(dance);state.name="Dance";controller.layers[0].stateMachine.defaultState=state;if(cheer!=null)controller.AddMotion(cheer).name="Cheer";}
  var paths=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/TruckPedestrianPlowing/Prefabs"}).Select(AssetDatabase.GUIDToAssetPath).OrderBy(p=>p).ToArray();var actors=new List<Animator>();for(int i=0;i<40;i++){var position=i<24?new Vector3((i%12-5.5f)*2.3f,0,12+i/12*2.5f):new Vector3(i%2==0?-24:24,0,-11+(i-24)/2*2.5f);actors.Add(SportsAudienceAuthoring.Spawn(AssetDatabase.LoadAssetAtPath<GameObject>(paths[i%paths.Length]),root,position,Vector3.zero,controller));}
  venue.audience=actors.ToArray();venue.meters=UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsInactive.Exclude).Where(r=>r.name=="Rear LED equalizer column").Select(r=>r.transform).ToArray();venue.meterHeights=venue.meters.Select(t=>t.localScale.y).ToArray();venue.lasers=new LineRenderer[8];for(int i=0;i<8;i++){var g=new GameObject("Slow sweeping concert laser "+i);g.transform.SetParent(root,false);g.transform.localPosition=new Vector3(i%2==0?-20:20,12,5+i/2*2);var line=g.AddComponent<LineRenderer>();line.positionCount=2;line.useWorldSpace=true;line.widthMultiplier=.035f;line.sharedMaterial=i%2==0?pink:cyan;line.startColor=line.endColor=i%2==0?new Color(1,.2f,.5f,.5f):new Color(.1f,.8f,1,.5f);venue.lasers[i]=line;}
  venue.fog=new ParticleSystem[2];for(int i=0;i<2;i++){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NWH/Vehicle Physics 2/Effects/Prefabs/ExhaustSmoke.prefab");var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab,root);g.name="Low rolling stage haze "+i;g.transform.localPosition=new Vector3(i==0?-17:17,.2f,8);foreach(var script in g.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(script);var ps=g.GetComponentInChildren<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.playOnAwake=false;main.loop=true;main.startLifetime=4;main.startSpeed=.3f;main.startSize=4;main.maxParticles=32;main.startColor=new Color(.35f,.2f,.6f,.12f);var emission=ps.emission;emission.rateOverTime=4;venue.fog[i]=ps;}
