  var confetti=new GameObject("Pooled original confetti celebration").AddComponent<ParticleSystem>();confetti.transform.position=new Vector3(0,12,1);confetti.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var cm=confetti.main;cm.playOnAwake=false;cm.loop=false;cm.duration=2;cm.startLifetime=3;cm.startSpeed=3;cm.startSize=.12f;cm.gravityModifier=.4f;cm.maxParticles=120;cm.startColor=new ParticleSystem.MinMaxGradient(Color.cyan,Color.magenta);var em=confetti.emission;em.rateOverTime=0;em.SetBursts(new[]{new ParticleSystem.Burst(0,100)});var sh=confetti.shape;sh.shapeType=ParticleSystemShapeType.Box;sh.scale=new Vector3(26,.2f,6);confetti.GetComponent<ParticleSystemRenderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckDemolitionDerby/Materials/Soft alpha smoke.mat");venue.celebration=confetti;
