 }
 static void StripPhysics(GameObject g){foreach(var j in g.GetComponentsInChildren<Joint>(true))UnityEngine.Object.DestroyImmediate(j);foreach(var c in g.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var b in g.GetComponentsInChildren<Rigidbody>(true))UnityEngine.Object.DestroyImmediate(b);foreach(var a in g.GetComponentsInChildren<UnityEngine.AI.NavMeshAgent>(true))UnityEngine.Object.DestroyImmediate(a);}
